import { expect, test } from 'bun:test';
import { retainedMappingRevision, RETAINED_NAMESPACES } from './candidate/services/main/src/modules/source/retained-record-normalization.ts';
import { SourceFieldProblem } from './candidate/services/main/src/modules/source/field-support-contract.ts';

function refusal(provider: string, namespace: string): unknown {
  try { retainedMappingRevision(provider, namespace); return null; }
  catch (error) { return error; }
}

test('all 28 declared retained provider/namespace pairs preserve their exact revisions', () => {
  let count = 0;
  for (const [provider, namespaces] of Object.entries(RETAINED_NAMESPACES)) {
    for (const namespace of namespaces) {
      expect(retainedMappingRevision(provider, namespace)).toBe(`${provider}-${namespace}-retained-map-v${namespace === 'release' ? 2 : 1}`);
      count++;
    }
  }
  expect(count).toBe(28);
});

test('ordinary unknown provider, empty provider and unsupported namespace refuse structurally', () => {
  for (const [provider, namespace] of [['unknown', 'vn'], ['', 'vn'], ['vndb', 'constructor']]) {
    const error = refusal(provider!, namespace!);
    expect(error).toBeInstanceOf(SourceFieldProblem);
    expect(error).toMatchObject({ status: 422, code: 'source_mapping_unverified' });
  }
});

for (const provider of ['constructor', '__proto__', 'toString']) {
  test(`unsupported retained provider ${provider} returns a structured mapping refusal`, () => {
    const error = refusal(provider, 'vn');
    expect(error).toBeInstanceOf(SourceFieldProblem);
    expect(error).toMatchObject({ status: 422, code: 'source_mapping_unverified' });
  });
}

