import { expect, test } from 'bun:test';
import { randomUUID } from 'node:crypto';
import { SourceRetainedFieldSupportStore, retainedAttachmentDigest } from './runtime/services/main/src/modules/source/field-support-retained.ts';
import { verifyRetainedField } from './runtime/services/main/src/modules/source/field-support-evidence.ts';
import { canonicalDigest } from './runtime/services/main/src/modules/source/retained-record-normalization.ts';
import { WorkReadSession, withWorkReadSession } from './runtime/services/main/src/modules/work/read-session.ts';
import { fusekiReadBudget } from './runtime/services/main/src/infrastructure/fuseki.ts';
import { projectDatasetFields } from './runtime/scripts/datasets/native/fields.ts';

// Unit counterexample: actual Source read/window/session methods; controlled SQL,
// retained custody and native/evidence owner ports. No native admission, SQL
// service or installed/public product claim is made by these prerequisites.
test('stable retained Structure evidence window completes its final dependency fence', async () => {
  const id = () => `https://rezics.com/id/${randomUUID()}`;
  const principalId = randomUUID(), supportId = randomUUID(), stepId = randomUUID();
  const principal = { issuer: 'https://account.test', subject: 'reader' };
  const record = { key: 'bangumi:episode:101', provider: 'bangumi', kind: 'episode', externalId: '101',
    title: 'Episode', native: 'episode', data: { id: 101, subject_id: 10, sort: 0.5, disc: 0, type: 1 } };
  const binding = { binding: id(), sourceRecord: id(), conversion: id(), recordDigest: canonicalDigest(record),
    mappingRevision: 'bangumi-episode-retained-map-v1', normalizationRevision: 'retained-record-json-v1' };
  const source = { key: record.key, provider: record.provider, namespace: record.kind, externalId: record.externalId,
    snapshot: 'snapshot', snapshotDigest: 'a'.repeat(64), recordDigest: binding.recordDigest, observations: [], intakes: [] };
  const evidence = { record, payload: { record }, rule: 'dataset-record-envelope-v1',
    conversion: { retainedRecord: binding }, fieldPlan: projectDatasetFields(record as never, source as never) };
  const native = { kind: 'structure-occurrence', owner: 'structure', target: id(), component: id(), structure: id(),
    profile: 'episode-list-v1', revision: id(), receipt: `urn:rezics:receipt:${'b'.repeat(64)}`, occurrence: id() };
  const request = { profile: 'source-field-support-attachment-v2', target: native.target,
    slot: 'structure-occurrence-v1#qualifier.values.position', occurrence: native.occurrence,
    context: native.structure, sourceRecord: binding.sourceRecord, conversion: binding.conversion,
    grain: 'episode', sourceField: 'sort', sourceOccurrence: null, expectedHead: native.revision, actingSubject: id(), native,
    evidence: { binding: binding.binding, recordDigest: binding.recordDigest, mappingRevision: binding.mappingRevision,
      field: { pointer: '/data/sort', presence: 'value', valueDigest: canonicalDigest(0.5) } } };
  const field = await verifyRetainedField(request as never, evidence as never);
  const acknowledgement = { receipt: native.receipt, admissionId: randomUUID(), scope: `work:edit:${native.target}`,
    action: 'work.edit', component: native.component, revision: native.revision, dataEpoch: randomUUID(), sequence: '1' };
  const admission = { profile: 'source-field-support-admission-v1', sourceRecord: binding.sourceRecord,
    conversion: binding.conversion, evidence: request.evidence, correspondence: field.correspondence,
    native, headGuarantee: 'verified-before-commit' };
  const digest = retainedAttachmentDigest(principalId, request as never, admission as never, acknowledgement as never);
  const saved = { support_id: supportId, step_id: stepId, request, request_digest: digest,
    retained_admission: admission, native_acknowledgement: acknowledgement,
    certificate: { profile: 'source-field-attachment-certificate-v1', receipt: `urn:rezics:receipt:${'c'.repeat(64)}`,
      requestDigest: digest, nativeReceipt: native.receipt }, created_at: new Date('2026-10-20T00:00:00Z'),
    withdrawal_id: null, reason: null, withdrawn_at: null };
  let windowLoads = 0, nativeReads = 0;
  const pool = { query: async (sql: string) => {
    if (sql.includes('field_support_generation')) return { rows: [{ generation: '1' }], rowCount: 1 };
    if (sql.includes('SELECT s.id,s.principal_id')) {
      windowLoads++;
      return { rows: [{ id: supportId, principal_id: principalId }], rowCount: 1 };
    }
    if (sql.includes('AS support_id')) return { rows: [saved], rowCount: 1 };
    if (sql.startsWith('SELECT 1 FROM source.retained_record_binding')) return { rows: [{}], rowCount: 1 };
    if (sql.startsWith('SELECT principal_id,conversion_id')) return { rows: [{ principal_id: principalId,
      conversion_id: binding.conversion.slice(-36) }], rowCount: 1 };
    throw new Error(`Unexpected SQL: ${sql}`);
  } };
  const deps = { environment: {}, access: { activePrincipalId: async () => principalId, assertRecoveryOpen: async () => {} } };
  const session = new WorkReadSession(deps as never, new Request('https://main.test/v1/evidence'),
    { actingSubject: request.actingSubject }, { dataEpoch: acknowledgement.dataEpoch, sequence: '1' });
  session.principal = principal;
  const store = new SourceRetainedFieldSupportStore(pool as never, {} as never, {} as never,
    { evidence: async () => evidence } as never, {
      structure: async () => { nativeReads++; return acknowledgement; },
      publicEvidence: async () => null,
    } as never);
  const budget = { callsLeft: 100, bytesLeft: 1_048_576, deadline: Infinity, signal: new AbortController().signal };
  await fusekiReadBudget.run(budget, () => withWorkReadSession(session, async () => {
    const window = await store.readEvidenceWindow(session, { target: native.target, slot: request.slot,
      occurrence: native.occurrence, context: native.structure, component: native.component, revision: native.revision });
    expect(window).toEqual({ items: [], generation: '1', more: false, next: null });
    expect(windowLoads).toBe(1);
    budget.deadline = performance.now() + 100;
    let failure: unknown;
    try { await session.fenceDependencies(); } catch (error) { failure = error; }
    console.log(JSON.stringify({ windowLoads, nativeReads, finalFenceError: failure instanceof Error ? failure.name : null }));
    expect(failure, 'unchanged input and withheld evidence must allow the final fence to complete').toBeUndefined();
  }));
});
